const frame=document.querySelector('iframe'),status=document.querySelector('#status'),metrics=document.querySelector('#metrics'),images=document.querySelector('#images');
const size=n=>n.toLocaleString('ko-KR')+' B';
let selectedWidth=390;
function measure(){try{const win=frame.contentWindow,doc=frame.contentDocument;if(!doc?.querySelector('#app')?.children.length){status.textContent='화면을 불러오는 중입니다.';return}const root=doc.documentElement;const overflow=Math.max(0,root.scrollWidth-root.clientWidth);const records=win.performance.getEntriesByType('resource').filter(r=>r.name.startsWith(location.origin+'/')&&/\.(webp|svg)(\?|$)/.test(r.name));const encoded=records.reduce((a,r)=>a+r.encodedBodySize,0),transfer=records.reduce((a,r)=>a+r.transferSize,0);status.textContent=overflow?'가로 넘침이 감지됐어요.':'가로 넘침이 없어요.';const pairs=[['프레임 CSS 폭',selectedWidth+'px'],['실제 innerWidth',win.innerWidth+'px'],['문서 clientWidth',root.clientWidth+'px'],['문서 scrollWidth',root.scrollWidth+'px'],['가로 넘침',overflow+'px'],['관측된 이미지 응답',records.length+'개'],['관측된 이미지 본문',size(encoded)],['관측된 이미지 전송',size(transfer)]];metrics.replaceChildren(...pairs.map(([name,value])=>{const div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;div.append(dt,dd);return div}));images.replaceChildren(...Array.from(doc.images).filter(img=>img.currentSrc&&img.complete).slice(0,12).map(img=>{const li=document.createElement('li');li.textContent=new URL(img.currentSrc).pathname+' · '+Math.round(img.getBoundingClientRect().width)+'px 표시';return li}))}catch{status.textContent='현재 브라우저의 보안 정책으로 프레임 측정이 제한됩니다.'}}
document.querySelectorAll('[data-width]').forEach(button=>button.addEventListener('click',()=>{const width=Number(button.dataset.width);if(![375,390,768,1280].includes(width))return;selectedWidth=width;frame.width=String(width);frame.title='온서 목업 '+width+'px 화면';document.querySelectorAll('[data-width]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));measure()}));
document.querySelector('#reload').addEventListener('click',()=>{frame.src='./';status.textContent='화면을 다시 불러오는 중입니다.'});
frame.addEventListener('load',measure);setInterval(measure,1000);
